import type { Bracket, Country, CountyData, Region } from './regions';
import type { CountryId } from './types';

type RegionEntry = [id: string, name: string, localities?: string[]];
type CuratedCountryId = 'CN' | 'BN' | 'BS' | 'SC' | 'ZM' | 'PG';
type CompactCountryId = 'ET' | 'ZW' | 'AO' | 'MW' | 'MZ' | 'DZ' | 'IQ' | 'RU' | 'BY' | 'KG' | 'TJ'
  | 'XK' | 'AD' | 'MC' | 'BB' | 'GY' | 'TL' | 'SB' | 'VU' | 'WS' | 'TO'
  | 'CI' | 'CM' | 'ZR' | 'SZ' | 'LS' | 'GA' | 'BJ' | 'BF' | 'ML' | 'NE' | 'TD' | 'SL' | 'LR' | 'GM'
  | 'SR' | 'BZ' | 'HN' | 'NI' | 'SV' | 'HT' | 'LC' | 'AG' | 'VC' | 'GD' | 'KN' | 'DM'
  | 'MG' | 'LI' | 'SM' | 'CV' | 'PW' | 'FM' | 'MH' | 'KI' | 'NR' | 'TV' | 'CK';

// Location-only entries never invent demographic statistics or local tax rates.
function localities(regionId: string, names: string[]): CountyData[] {
  return names.map((name, index) => ({
    id: `${regionId}-LOCAL-${index + 1}`, name, seat: name, population: 0, medianIncome: 0,
    propertyTaxRate: 0, localSalesTaxRate: 0, localIncomeTaxRate: 0, labelOnly: true,
    rules: 'Location label only. No additional tax or property rate is applied automatically.',
  }));
}

function makeRegions(entries: RegionEntry[], authority: string, citation: string, salesTax: number, description: string): Region[] {
  return entries.map(([id, name, cities = []]) => ({
    id, name, code: id, cities, counties: localities(id, cities), propertyTax: 0, salesTax, flatTax: 0,
    medianIncome: 0, costOfLivingIndex: 0, referenceOnly: true, taxStructure: 'National reference; local costs entered separately',
    statuteCitation: citation, governingBody: authority, description, taxRegime: 'national',
  }));
}

function referenceCountry(config: Omit<Country, 'years' | 'regions'> & { brackets: Bracket[]; allowance?: number; locations: RegionEntry[]; salesTax: number; citation: string }): Country {
  const { brackets, allowance = 0, locations, salesTax, citation, ...country } = config;
  return {
    ...country,
    coverageNote: country.coverageNote || 'Dated employment-income reference. Localities identify your location; local taxes and assessed property bills require your own inputs.',
    years: [{ id: country.taxYear, label: `${country.taxYear} reference`, deduction: { single: allowance, joint: allowance, head: allowance }, federal: { single: brackets, joint: brackets, head: brackets } }],
    regions: makeRegions(locations, country.legalBody, citation, salesTax, country.rules),
  };
}

const annualize = (brackets: Bracket[]): Bracket[] => brackets.map(([cap, rate]) => [cap * 12, rate]);

interface CompactCountry {
  id: CompactCountryId; name: string; authority: string; currency: string; symbol: string; locale?: string;
  regionLabel: string; localityLabel: string; year: string; vat: number; allowance?: number;
  brackets: Bracket[]; rules: string; citation: string; source: [name: string, url: string];
  locations: RegionEntry[];
}

