export function expandRegionalCoverage(countries: Record<CountryId, Country>) {
  for (const [id, entries] of Object.entries(regionExpansions)) {
    const country = countries[id as CountryId];
    const reference = country.regions[0];
    const existing = new Set(country.regions.map(region => region.id));
    const added = entries!.filter(entry => !existing.has(entry[0]));
    country.regions.push(...makeRegions(added, country.legalBody, reference.statuteCitation, reference.salesTax,
      'Uses the existing national reference pack. Municipal charges, professional taxes, contribution bases and exemptions are not inferred from a location label. Enter applicable local amounts explicitly.'));
    country.regions.sort((a, b) => a.name.localeCompare(b.name, 'en'));
  }
  countries.IN.regionLabel = 'State / union territory';
  countries.DE.localityLabel = 'City / municipality';
  countries.JP.localityLabel = 'City / ward';
  countries.GB.localityLabel = 'City / local area';
  countries.AU.localityLabel = 'City / council area';
  countries.NZ.localityLabel = 'City / local area';

  for (const country of Object.values(countries)) {
    for (const region of country.regions) {
      if (!region.counties.length && region.cities.length) region.counties = localities(region.id, region.cities);
      if (region.id === 'OTHER') { region.customTax = true; region.referenceOnly = true; }
    }
    if (!country.regions.some(region => region.id === 'OTHER')) country.regions.push({
      id: 'OTHER', code: 'OTHER', name: 'Other region (custom estimate)', cities: [], counties: [], propertyTax: 0, salesTax: 0,
      medianIncome: 0, costOfLivingIndex: 0, taxStructure: 'Custom regional estimate', statuteCitation: 'No regional schedule loaded',
      governingBody: country.legalBody, description: 'The selected national reference still applies. Enter regional and local rates yourself; zero is an unset assumption, not a verified tax exemption.',
      customTax: true, referenceOnly: true,
    });
  }
}